<?php require __DIR__.'/../includes/bootstrap.php';require_admin();$pageTitle='Issue / Return';$basePath='../';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if($_POST['action']==='issue'){$mid=(int)$_POST['member_id'];$bid=(int)$_POST['book_id'];$qty=max(1,(int)$_POST['quantity']);$due=$_POST['due_date'];$pdo->beginTransaction();try{$s=$pdo->prepare('SELECT * FROM books WHERE id=? FOR UPDATE');$s->execute([$bid]);$b=$s->fetch();$s=$pdo->prepare('SELECT * FROM members WHERE id=? FOR UPDATE');$s->execute([$mid]);$m=$s->fetch();$c=$pdo->prepare('SELECT COALESCE(SUM(quantity),0) FROM loans WHERE member_id=? AND status="issued"');$c->execute([$mid]);if(!$b||!$m||$m['status']!=='active'||$b['available_copies']<$qty||((int)$c->fetchColumn()+$qty)>(int)$m['max_books'])throw new Exception('Check member status, available copies and borrowing limit.');$pdo->prepare('INSERT INTO loans(member_id,book_id,quantity,issue_date,due_date,issued_by) VALUES(?,?,?,?,?,?)')->execute([$mid,$bid,$qty,date('Y-m-d'),$due,current_user()['id']]);$pdo->prepare('UPDATE books SET available_copies=available_copies-? WHERE id=?')->execute([$qty,$bid]);$pdo->commit();audit($pdo,'Issued book',$b['title'].' to '.$m['name']);flash('success','Book issued successfully.');}catch(Throwable $e){$pdo->rollBack();flash('error',$e->getMessage());}}elseif($_POST['action']==='return'){$id=(int)$_POST['loan_id'];$pdo->beginTransaction();try{$s=$pdo->prepare('SELECT l.*,b.title FROM loans l JOIN books b ON b.id=l.book_id WHERE l.id=? AND l.status="issued" FOR UPDATE');$s->execute([$id]);$l=$s->fetch();if(!$l)throw new Exception('Active loan not found.');$today=date('Y-m-d');$days=max(0,(int)floor((strtotime($today)-strtotime($l['due_date']))/86400));$amount=$days*(float)setting($pdo,'fine_per_day',10);$pdo->prepare('UPDATE loans SET status="returned",return_date=?,returned_by=? WHERE id=?')->execute([$today,current_user()['id'],$id]);$pdo->prepare('UPDATE books SET available_copies=available_copies+? WHERE id=?')->execute([$l['quantity'],$l['book_id']]);if($amount>0)$pdo->prepare('INSERT INTO fines(loan_id,member_id,book_id,amount,status) VALUES(?,?,?,? ,"unpaid")')->execute([$id,$l['member_id'],$l['book_id'],$amount]);$pdo->commit();audit($pdo,'Returned book',$l['title'].'; fine '.money($amount));flash('success','Book returned. Final fine: '.money($amount));}catch(Throwable $e){$pdo->rollBack();flash('error',$e->getMessage());}}redirect('loans.php');}
$members=$pdo->query('SELECT id,member_code,name FROM members WHERE status="active" ORDER BY name')->fetchAll();$books=$pdo->query('SELECT id,title,author,available_copies FROM books WHERE available_copies>0 ORDER BY title')->fetchAll();$loans=$pdo->query('SELECT l.*,m.name member_name,m.member_code,b.title,b.author FROM loans l JOIN members m ON m.id=l.member_id JOIN books b ON b.id=l.book_id ORDER BY l.id DESC LIMIT 100')->fetchAll();require __DIR__.'/../includes/layout_top.php';?><div class="two-col"><div class="panel"><h3>Issue a book</h3><p class="muted">Only administrators can issue books to registered members.</p><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="issue"><label class="wide">Member<select name="member_id" required><option value="">Select member</option><?php foreach($members as $m):?><option value="<?=$m['id']?>"><?=e($m['member_code'].' · '.$m['name'])?></option><?php endforeach;?></select></label><label class="wide">Book<select name="book_id" required><option value="">Select available book</option><?php foreach($books as $b):?><option value="<?=$b['id']?>"><?=e($b['title'].' — '.$b['author'].' ('.$b['available_copies'].' available)')?></option><?php endforeach;?></select></label><label>Quantity<input type="number" name="quantity" min="1" value="1" required></label><label>Due date<input type="date" name="due_date" min="<?=date('Y-m-d')?>" value="<?=date('Y-m-d',strtotime('+'.(int)setting($pdo,'loan_days',14).' days'))?>" required></label><div class="wide"><button class="btn primary">Confirm issue</button></div></form></div><div class="panel"><h3>Circulation rules</h3><div class="rule"><b><?=e(setting($pdo,'loan_days',14))?> days</b><span>Default loan period</span></div><div class="rule"><b><?=money(setting($pdo,'fine_per_day',10))?></b><span>Fine per overdue day</span></div><p class="muted">The member can see issued books and fine details in their own account. Members cannot issue or return books.</p></div></div><div class="panel"><div class="panel-head"><div><h3>Loan records</h3><p>Latest 100 circulation records.</p></div></div><div class="table-wrap"><table><thead><tr><th>Member</th><th>Book</th><th>Issue / Due</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($loans as $l):?><tr><td><?=e($l['member_name'])?><small><?=e($l['member_code'])?></small></td><td><?=e($l['title'])?><small>Qty: <?=$l['quantity']?></small></td><td><?=e($l['issue_date'])?><small>Due: <?=e($l['due_date'])?></small></td><td><span class="pill <?=$l['status']==='issued'?'warning':'success'?>"><?=$l['status']?></span></td><td><?php if($l['status']==='issued'):?><form method="post" onsubmit="return confirm('Confirm book return?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="return"><input type="hidden" name="loan_id" value="<?=$l['id']?>"><button class="btn small">Record return</button></form><?php else:?>Returned <?=e($l['return_date'])?><?php endif;?></td></tr><?php endforeach;?><?php if(!$loans):?><tr><td colspan="5" class="empty">No loan records.</td></tr><?php endif;?></tbody></table></div></div><?php require __DIR__.'/../includes/layout_bottom.php';?>
